import json,pathlib,hashlib
R=pathlib.Path(__file__).resolve().parent;W=R.parent/'workspace'
def save(n,v):(R/n).write_text(json.dumps(v,indent=2)+'\n')
a=json.load(open(R/'source-analysis.json'));before=json.load(open(R/'package-hashes-before.json'));now={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in W.iterdir() if p.is_file()};assert before==now;save('package-hashes-after.json',{'files':now,'unchanged':True,'directory_entries':sorted(p.name for p in W.iterdir())})
def check(status,paths,details):return {'status':status,'evidence_paths':paths,'details':details}
checks={
'source_replay':check('failed',['source-replay.json','source-replay-records.json','missing-reproduction.json','reproduce_missing.py','source-extract.json'],'12 complete source banks replay; q-20598, q-20589 and canonical e-4709 are unavailable. Captured bad key for q-131590 is correctly repaired to (-6,1,1).'),
'math':check('passed',['math-results.json','delivered-math.json','audit.py'],'146 records checked independently from displayed equations and choices, including every displayed row operation. All 65 normalized survivors also checked; no failures.'),
'variety':check('passed',['controlled-records.json','random-records.json','variation-coverage.json','selection-analysis.json','delivery-sample/delivery.json','delivery-batch/delivery.json'],'All five bank roles and four justified coefficient masks exercised per implemented profile. Fresh random 60/60 and exact batch 5/5 survive real filtering. Missing source replay is a separate failure. Selection branches examined analytically; live policy/history and allocated IDs unavailable.'),
'scope':check('passed',['scope.json','source-analysis.json','math-results.json'],'Retains easy nonsingular already-echelon 3x3 systems, integer arithmetic, two/three backward elimination operations and observed radio representations.'),
'grading':check('passed',['grader-input.json','grader-results.json','counterfactual-results.json'],'Native learner grader: 146 correct choices accepted, 584 distractors rejected, including old/new counterfactual responses. All fields radio; free-entry equivalence inapplicable.'),
'rendering':check('passed',['visual-inspection.json','render/rendering.json','render-pairs/rendering.json','render-delivered/rendering.json'],'Actual UI rendered 6 representatives, all 9 counterfactual records and all 5 normalized batch survivors. Screenshots inspected across matrix/vector/text controls and solutions.'),
'packaging':check('passed',['packaging.json','package-hashes-before.json','package-hashes-after.json','audit.py'],'Python 3.13.5 and SymPy 1.14.0 match exact nested manifest dependency contract. Determinism, relocation and rejection checks pass. Package unchanged; no database writes/publication.'),
'decision_variation':check('passed',['pedagogical-variation.json','evidence-contract.json','counterfactual-records.json','counterfactual-results.json','shortcut-results.json','ui-order-results.json','affected-inventory.json','inventory-assessment.json'],'Relevant/irrelevant pairs verified across all three representations using independent math, native grading and actual UI. Conditional bank-geometry probes have counterexamples. Raw position bias is removed by actual UI ordering. No universal incidental cue demonstrated in exact batch. Inventory examined at basis 5370; no affected generated instance demonstrated for missing-profile defect. Finite and conditional-selection limits recorded.')}
finding={'kind':'source_fidelity','description':'Replay registry contains 12 profiles at stored source basis 3933; captured source basis 5370 supplies 14 questions plus a canonical example. Fully evidenced easy q-20598 cannot be reproduced; q-20589 and e-4709 are also absent. This is a source-coverage defect, not an instance math or batch-selection failure.','source_refs':['af324f37-b688-5363-a6a2-fc8d79b31ad4 (q-20598)','5eba1f2e-9d1f-5a78-8bbb-878c7c8cae0e (q-20589)','de738faf-e020-5058-b6a5-48020212fbc4 (e-4709)','tutorial f74e6075-9c2a-5495-ab21-470711559f2a: three-pivot algorithm','generate/principles.md: reproduce observed prompts, complete banks and solutions before extending'],'reproduction':'From evidence_root: /home/jake/Developer/Course_Academy/.venv/bin/python -B reproduce_missing.py --workspace ../workspace (exit 1; missing-reproduction.json). Minimal call: generator.generate(difficulty="easy", seed=731, template="q-20598", replay=True) -> KeyError("q-20598"). Its captured system x+3y-9z=30, y-3z=10, z=-3 has solution (0,1,-3), present in its five-choice RREF bank.','requested_change':'Update the source-profile registry and family-wide completeness check against captured target-KP cases. Add q-20598 with its full bank; handle q-20589 with its inferred unique key and documented capture gaps; support canonical replay without inventing an uncaptured original bank. Preserve the valid source-key correction and working role/mask variation. Rerun reproduce_missing.py and focused source regressions.'}
report={'verdict':'revise','summary':'Source replay is incomplete: q-20598, q-20589 and e-4709 raise KeyError. Other tested checks pass within stated limits; package unchanged.','source_analysis':{k:a[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']},'checks':checks,'findings':[finding]}
